using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Threading.Tasks;using Mewgic.Core;
public static class Part12AModelTests
{
    public static Task Active;static int checks;static void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}
    public static void Run(){Active=Task.Run(()=>{try{RunAll();}catch(Exception e){File.WriteAllText("docs/ProductionReports/Part12A/MODEL_TESTS.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{success=false,checks,error=e.ToString()},Newtonsoft.Json.Formatting.Indented));}});}
    static void RunAll()
    {
        checks=0;var golden=new StablePrng(1);Check(golden.Next()==270369u&&golden.Next()==67634689u&&golden.Next()==2647435461u,"Xorshift32 altın vektör");string folder="docs/ProductionReports/Part12A/";var pool=new List<GeneratedLevel>();var unique=new HashSet<string>();int tried=0;
        foreach(int colors in new[]{3,4})for(int seed=1,added=0;seed<=4000&&added<96;seed++){
            tried++;var r=new GeneratorRequest{level=300000+seed,seed=(uint)(seed*7937+colors*23),colors=colors,target=colors==3?(seed%4==0?LevelDifficulty.Easy:LevelDifficulty.Normal):(seed%3==0?LevelDifficulty.Expert:seed%3==1?LevelDifficulty.Hard:LevelDifficulty.Normal)};
            var result=LevelGenerator.Generate(r);if(result.level!=null&&unique.Add(result.level.signature)){pool.Add(result.level);added++;}
            if(seed%25==0)File.WriteAllText(folder+"PROGRESS.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{phase="fallback",colors,seed,added}));
        }
        Check(pool.Count==192,"192 benzersiz doğrulanmış yedek bölüm");foreach(var l in pool)l.Validate();File.WriteAllText("Assets/Resources/Levels/GeneratedFallbacks.json",Newtonsoft.Json.JsonConvert.SerializeObject(pool));
        var ring=new Queue<string>();var rows=new List<object>();var all=new HashSet<string>();int direct=0,fallback=0,failed=0,repeats=0,limited=0,dupes=0,shapeRejected=0,difficultyRejected=0,totalCandidates=0;var timings=new List<double>();
        for(int n=0;n<1000;n++){
            int id=n+3;var r=GeneratorRequest.ForLevel(id);string[] recent=ring.ToArray();var sw=Stopwatch.StartNew();var result=LevelGenerator.Resolve(r,recent,pool.ToArray());double ms=sw.Elapsed.TotalMilliseconds;timings.Add(ms);limited+=result.limits;dupes+=result.duplicates;shapeRejected+=result.shapeRejected;difficultyRejected+=result.difficultyRejected;totalCandidates+=result.candidates;
            if(result.level==null){failed++;rows.Add(new{id,success=false,ms,result.failure});continue;}var l=result.level;l.Validate();Check(LevelGenerator.Exact(l.Export(),LevelGenerator.Reproduce(l)),"Kabul edilen seed geçmişten bağımsız aynı düzeni üretir");if(l.fallback)fallback++;else direct++;
            Check(!recent.Contains(l.signature),"Yakın 64 içinde renk/şişe permütasyon tekrarı yok");if(!all.Add(l.signature))repeats++;
            var again=LevelGenerator.Resolve(r,recent,pool.ToArray());Check(again.level!=null&&LevelGenerator.Exact(l.Export(),again.level.Export())&&l.signature==again.level.signature&&l.difficulty.score==again.level.difficulty.score,"Seed/bütçe/geçmiş deterministik");
            var renamed=l.Export().Reverse().Select(b=>b.Select(c=>3-c).ToArray()).ToArray();Check(LevelSignatures.Canonical(renamed)==l.signature,"Renk isimleri ve şişe sırası imza eşdeğeri");
            var model=new Puzzle(l.Export());string original=PuzzleSolver.StateKey(model.Export());Check(model.Pour(-1,0)==0&&model.Pour(0,0)==0&&model.Moves==0,"İmkânsız indeks/öz aktarım engelli");var move=l.solution[0];Check(model.Pour(move.source,move.target)>0&&model.Undo()&&PuzzleSolver.StateKey(model.Export())==original,"Gerçek Undo");model.Pour(move.source,move.target);model.Restart();Check(model.Moves==0&&LevelGenerator.Exact(model.Export(),l.Export()),"Restart aynı bölüm");
            var ledger=new ProgressLedger(new ProgressData(),_=>{});var tools=new BoosterActions(model,ledger,model.Count);Check(tools.Hint(out var hint)&&new Puzzle(model.Export()).Pour(hint.Source,hint.Target)>0,"Hint geçerli doğrulanmış hamle");Check(tools.Shuffle()&&PuzzleSolver.Solve(model.Export()).Status==SearchStatus.Solved,"Shuffle çözümü korur");
            ring.Enqueue(l.signature);while(ring.Count>64)ring.Dequeue();rows.Add(new{id,success=true,ms,l.fallback,l.seed,l.requestSeed,colors=l.colors,target=r.target.ToString(),actual=l.difficulty.measured.ToString(),l.difficulty.score,l.difficulty.optimalMoves,l.difficulty.visited,l.difficulty.stored,l.difficulty.peakQueue,l.difficulty.deadEndStates,result.candidates,result.limits,result.duplicates});
            if(n%25==0)File.WriteAllText(folder+"PROGRESS.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{phase="1000-seeds",completed=n+1,direct,fallback,failed}));
        }
        var tiny=new GenerationBudget{candidates=1,statesPerCandidate=1,totalStates=1};var forced=LevelGenerator.Resolve(GeneratorRequest.ForLevel(7),Array.Empty<string>(),pool.ToArray(),tiny);Check(forced.level!=null&&forced.level.fallback&&forced.limits>0,"Bütçede doğrulanamayan adaya karşı doğrulanmış havuz");Check(PuzzleSolver.Solve(new[]{new[]{0,1,0,1},new[]{1,0,1,0}}).Status==SearchStatus.Unsolvable,"Gerçek çıkmaz ayrı sonuç");Check(PuzzleSolver.Solve(pool[0].Export(),1).Status==SearchStatus.LimitReached,"Arama sınırı çözülemez değildir");
        var tutorial=LevelGenerator.Generate(new GeneratorRequest{level=5000,seed=17,colors=2,target=LevelDifficulty.Tutorial});Check(tutorial.level!=null,"Tutorial iki renkli doğrulanmış üretim");
        var oneEmpty=LevelGenerator.Generate(new GeneratorRequest{level=5001,seed=31,colors=3,emptyBottles=1,target=LevelDifficulty.Normal});Check(oneEmpty.level!=null&&oneEmpty.level.Export().Count(b=>b.Length==0)==1,"Tek boş şişe parametresi");
        int bad=0;foreach(var r in new[]{new GeneratorRequest{level=0},new GeneratorRequest{level=3,colors=0},new GeneratorRequest{level=3,capacity=5},new GeneratorRequest{level=3,version=999},new GeneratorRequest{level=3,emptyBottles=0}}){try{LevelGenerator.Generate(r);}catch(ArgumentException){bad++;}}Check(bad==5,"Hatalı/sıfır/desteklenmeyen parametreler reddedilir");
        string temp=Path.Combine(Path.GetTempPath(),"Mewgic-Part12A-"+Guid.NewGuid().ToString("N"));try{var archive=new FileLevelArchive(temp);var first=pool[0].Copy();first.level=4000;archive.Write(first);Check(archive.TryRead(4000,out var stored)&&LevelGenerator.Exact(first.Export(),stored.Export()),"Kalıcı tanım Save/Load");var future=first.Copy();future.version=999;future.level=4001;archive.Write(future);Check(archive.TryRead(4001,out stored)&&stored.version==999&&LevelGenerator.Exact(future.Export(),stored.Export()),"Yeni üretici sürümü eski pin verisini yeniden üretmez");File.WriteAllText(Path.Combine(temp,"level-4000.json"),"broken");Check(archive.TryRead(4000,out stored)&&stored.signature==first.signature,"Bozuk pin doğrulanmış yedekten okunur");File.WriteAllText(Path.Combine(temp,"level-4000.json.backup"),"broken");bool rejected=false;try{archive.TryRead(4000,out _);}catch(InvalidDataException){rejected=true;}Check(rejected,"İki bozuk pin rastgele yeni bölümle değiştirilmez");}finally{Directory.Delete(temp,true);}
        Check(failed==0,"1000 kombinasyonun tamamı doğrulandı");timings.Sort();File.WriteAllText(folder+"SEEDS.json",Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));File.WriteAllText(folder+"MODEL_TESTS.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{success=true,checks,combinations=1000,direct,fallback,failed,totalUnique=all.Count,repeatsOutsideWindow=repeats,candidateLimits=limited,candidateDuplicates=dupes,totalCandidates,candidateShapeRejected=shapeRejected,candidateDifficultyRejected=difficultyRejected,fallbackPool=pool.Count,fallbackPoolAttempts=tried,medianMs=timings[500],p95Ms=timings[950],maxMs=timings.Last(),meanMs=timings.Average()},Newtonsoft.Json.Formatting.Indented));
    }
    public static void Tune(){Task.Run(()=>{var list=new List<object>();for(int id=3;id<43;id++){var request=GeneratorRequest.ForLevel(id);var watch=Stopwatch.StartNew();var result=LevelGenerator.Generate(request);list.Add(new{id,request.target,ms=watch.ElapsedMilliseconds,ok=result.level!=null,result.candidates,result.limits,result.difficultyRejected,metrics=result.level?.difficulty});}File.WriteAllText("docs/ProductionReports/Part12A/TUNE.json",Newtonsoft.Json.JsonConvert.SerializeObject(list,Newtonsoft.Json.Formatting.Indented));});}
}
